-- ============================================================================
-- Artigo de FAQ: encerramento de cliente, do pedido à inativação.
--
-- `origem_sistema = true`: é artigo do sistema, não escrito por usuário.
-- Idempotente pelo slug (que é UNIQUE) — o deploy não reaplica o arquivo, mas
-- rodar a mão duas vezes não duplica nem sobrescreve edição feita na tela.
--
-- `id` e `updated_at` explícitos: `@default(cuid())` e `@updatedAt` são do
-- Prisma, não do banco — a coluna nasce sem default (lição de 04/09).
--
-- O desenho do fluxo é SVG inline, não imagem: acompanha o tema, continua
-- nítido em qualquer tela e não depende de upload — a FAQ não tem onde
-- hospedar arquivo hoje. Os artigos de sistema já usam SVG inline nos ícones.
-- ============================================================================

INSERT INTO faq_artigos (
  id, slug, titulo, descricao, modulo, modulo_color, icon, categoria, tags,
  conteudo_html, publicado, ordem, origem_sistema, criado_por, created_at, updated_at
)
SELECT
  gen_random_uuid()::text,
  'encerramento-cliente',
  'Encerramento de cliente: do pedido à inativação',
  'Como registrar o pedido de saída, o que a cadeia dispara sozinha e o que cabe a cada área até o cliente ser inativado.',
  'Clientes',
  '#10b981',
  'DoorOpen',
  'Cadastros',
  '{encerramento,offboarding,distrato,saída,cliente,fluxo,gatilho,inativação}',
  '<div class="space-y-4"><div class="relative flex flex-col min-w-0 break-words bg-card text-card-foreground bg-clip-border border-0 rounded-[.25rem] shadow-[0_1px_2px_rgba(56,65,74,0.15)]"><div class="flex-1 p-5 space-y-3"><div class="flex items-center gap-2 pb-2 border-b"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="h-4 w-4" style="color: #0891b2;"><circle cx="12" cy="12" r="10"></circle><path d="M12 16v-4"></path><path d="M12 8h.01"></path></svg><h3 class="text-sm font-bold" id="o-que-resolve" style="color: #0891b2;">O que este fluxo resolve</h3></div><div class="space-y-2 text-sm"><p class="text-foreground/70">Já aconteceu de um cliente sair e uma área continuar trabalhando para ele durante meses, sem saber. A causa não era desleixo: <strong>a saída era registrada num lugar e o trabalho acontecia em outro</strong>, e nada ligava os dois. Este fluxo liga.</p><p class="text-foreground/70">A partir do momento em que o comercial registra o pedido de encerramento, a cadeia inteira começa sozinha: convoca as áreas, cobra a data de encerramento de cada uma, acompanha as entregas e só então inativa o cliente.</p></div></div></div><div class="relative flex flex-col min-w-0 break-words bg-card text-card-foreground bg-clip-border border-0 rounded-[.25rem] shadow-[0_1px_2px_rgba(56,65,74,0.15)]"><div class="flex-1 p-5 space-y-3"><div class="flex items-center gap-2 pb-2 border-b"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="h-4 w-4" style="color: #0891b2;"><circle cx="12" cy="12" r="10"></circle><path d="M12 16v-4"></path><path d="M12 8h.01"></path></svg><h3 class="text-sm font-bold" id="conceitos" style="color: #0891b2;">Conceitos importantes</h3></div><div class="space-y-2 text-sm"><div class="flex flex-col sm:flex-row sm:items-baseline gap-1 sm:gap-3"><span class="font-semibold text-foreground sm:w-44 shrink-0">Encerramento solicitado</span><span class="text-foreground/70">O cliente avisou que quer sair. É um estado do cadastro, não um passo do fluxo. O cliente <strong>continua ATIVO</strong> — ninguém para de trabalhar por causa do pedido, mas a cadeia de saída já começou.</span></div><div class="flex flex-col sm:flex-row sm:items-baseline gap-1 sm:gap-3"><span class="font-semibold text-foreground sm:w-44 shrink-0">Gatilho</span><span class="text-foreground/70">A regra que liga um evento do cadastro a um fluxo. Fica em uma tabela de configuração: "quando este evento acontecer, e se esta condição bater, inicie aquele serviço".</span></div><div class="flex flex-col sm:flex-row sm:items-baseline gap-1 sm:gap-3"><span class="font-semibold text-foreground sm:w-44 shrink-0">Aguardando confirmação</span><span class="text-foreground/70">A execução nasce parada, de propósito. Um pedido registrado por engano abriria distrato, convocaria as áreas e falaria com o cliente — por isso alguém confirma antes.</span></div><div class="flex flex-col sm:flex-row sm:items-baseline gap-1 sm:gap-3"><span class="font-semibold text-foreground sm:w-44 shrink-0">Data de encerramento</span><span class="text-foreground/70">A data em que <strong>aquela área</strong> para de atender. É por área, não por cliente: o fiscal pode encerrar em 30/09 e o trabalhista só depois da rescisão dos funcionários.</span></div><div class="flex flex-col sm:flex-row sm:items-baseline gap-1 sm:gap-3"><span class="font-semibold text-foreground sm:w-44 shrink-0">Distrato</span><span class="text-foreground/70">O encerramento formal do contrato. A Resolução CFC nº 1.590/2020 pede que ele especifique quando a responsabilidade de cada parte cessa — é a mesma data que alimenta o encerramento por área.</span></div></div></div></div><div class="relative flex flex-col min-w-0 break-words bg-card text-card-foreground bg-clip-border border-0 rounded-[.25rem] shadow-[0_1px_2px_rgba(56,65,74,0.15)]"><div class="flex-1 p-5 space-y-3"><div class="flex items-center gap-2 pb-2 border-b"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="h-4 w-4" style="color: #10b981;"><circle cx="6" cy="19" r="3"></circle><path d="M9 19h8.5a3.5 3.5 0 0 0 0-7h-11a3.5 3.5 0 0 1 0-7H15"></path><circle cx="18" cy="5" r="3"></circle></svg><h3 class="text-sm font-bold" id="desenho" style="color: #10b981;">O desenho da cadeia</h3></div><div class="space-y-2 text-sm"><p class="text-foreground/70">As caixas em verde são serviços com passos a executar. A roxa é uma pergunta: a execução <strong>pausa</strong> até alguém responder, e segue só pelo ramo escolhido. As tracejadas em âmbar são a parte automática.</p><div class="overflow-x-auto -mx-1 px-1"><svg viewBox="0 0 760 640" width="100%" style="min-width:640px; color: currentColor;" role="img" aria-label="Cadeia do encerramento de cliente"><defs><marker id="pta" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M 0 0 L 10 5 L 0 10 z" fill="currentColor" fill-opacity="0.35"></path></marker></defs><rect x="230" y="10" width="300" height="52" rx="8" fill="color-mix(in srgb, #d97706 9%, transparent)" stroke="#d97706" stroke-width="1.5"></rect><text x="380.0" y="32" text-anchor="middle" font-size="13" font-weight="600" fill="#d97706">Pedido de encerramento</text><text x="380.0" y="49" text-anchor="middle" font-size="11" fill="currentColor" opacity="0.65">comercial registra — cliente segue ATIVO</text><line x1="380" y1="62" x2="380" y2="88" stroke="currentColor" stroke-opacity="0.35" stroke-width="1.5" marker-end="url(#pta)"></line><text x="430" y="80" text-anchor="middle" font-size="10.5" font-weight="600" fill="currentColor" opacity="0.6">gatilho</text><rect x="230" y="90" width="300" height="52" rx="8" fill="color-mix(in srgb, #d97706 9%, transparent)" stroke="#d97706" stroke-width="1.5" stroke-dasharray="5 4"></rect><text x="380.0" y="112" text-anchor="middle" font-size="13" font-weight="600" fill="#d97706">Execução aguardando confirmação</text><text x="380.0" y="129" text-anchor="middle" font-size="11" fill="currentColor" opacity="0.65">nada anda até alguém confirmar</text><line x1="380" y1="142" x2="380" y2="168" stroke="currentColor" stroke-opacity="0.35" stroke-width="1.5" marker-end="url(#pta)"></line><rect x="230" y="170" width="300" height="52" rx="8" fill="color-mix(in srgb, #10b981 9%, transparent)" stroke="#10b981" stroke-width="1.5"></rect><text x="380.0" y="192" text-anchor="middle" font-size="13" font-weight="600" fill="#10b981">Offboarding de Cliente</text><text x="380.0" y="209" text-anchor="middle" font-size="11" fill="currentColor" opacity="0.65">receber a rescisão · convocar as áreas</text><line x1="380" y1="222" x2="380" y2="248" stroke="currentColor" stroke-opacity="0.35" stroke-width="1.5" marker-end="url(#pta)"></line><rect x="215" y="250" width="330" height="52" rx="8" fill="color-mix(in srgb, #7c3aed 9%, transparent)" stroke="#7c3aed" stroke-width="1.5"></rect><text x="380.0" y="272" text-anchor="middle" font-size="13" font-weight="600" fill="#7c3aed">Imediata ou em uma data?</text><text x="380.0" y="289" text-anchor="middle" font-size="11" fill="currentColor" opacity="0.65">a execução pausa esperando a resposta</text><path d="M380 302 L380 320 L150 320 L150 344" stroke="currentColor" stroke-opacity="0.35" stroke-width="1.5" fill="none" marker-end="url(#pta)"></path><path d="M380 302 L380 320 L610 320 L610 344" stroke="currentColor" stroke-opacity="0.35" stroke-width="1.5" fill="none" marker-end="url(#pta)"></path><text x="150" y="336" text-anchor="middle" font-size="10.5" font-weight="600" fill="currentColor" opacity="0.6">Imediata</text><text x="610" y="336" text-anchor="middle" font-size="10.5" font-weight="600" fill="currentColor" opacity="0.6">Em uma data</text><rect x="30" y="348" width="240" height="52" rx="8" fill="color-mix(in srgb, #10b981 9%, transparent)" stroke="#10b981" stroke-width="1.5"></rect><text x="150.0" y="370" text-anchor="middle" font-size="13" font-weight="600" fill="#10b981">Encerrar agora</text><text x="150.0" y="387" text-anchor="middle" font-size="11" fill="currentColor" opacity="0.65">inativa e comunica as áreas</text><rect x="490" y="348" width="240" height="52" rx="8" fill="color-mix(in srgb, #10b981 9%, transparent)" stroke="#10b981" stroke-width="1.5"></rect><text x="610.0" y="370" text-anchor="middle" font-size="13" font-weight="600" fill="#10b981">Acompanhar até a data</text><text x="610.0" y="387" text-anchor="middle" font-size="11" fill="currentColor" opacity="0.65">agenda e cobra quem não informou</text><path d="M150 400 L150 424 L380 424 L380 448" stroke="currentColor" stroke-opacity="0.35" stroke-width="1.5" fill="none" marker-end="url(#pta)"></path><path d="M610 400 L610 424 L380 424" stroke="currentColor" stroke-opacity="0.35" stroke-width="1.5" fill="none"></path><rect x="230" y="450" width="300" height="52" rx="8" fill="color-mix(in srgb, #10b981 9%, transparent)" stroke="#10b981" stroke-width="1.5"></rect><text x="380.0" y="472" text-anchor="middle" font-size="13" font-weight="600" fill="#10b981">Encerrar por área</text><text x="380.0" y="489" text-anchor="middle" font-size="11" fill="currentColor" opacity="0.65">datas, entregas, documentos e acessos</text><line x1="380" y1="502" x2="380" y2="528" stroke="currentColor" stroke-opacity="0.35" stroke-width="1.5" marker-end="url(#pta)"></line><rect x="230" y="530" width="300" height="52" rx="8" fill="color-mix(in srgb, #10b981 9%, transparent)" stroke="#10b981" stroke-width="1.5"></rect><text x="380.0" y="552" text-anchor="middle" font-size="13" font-weight="600" fill="#10b981">Fechamento</text><text x="380.0" y="569" text-anchor="middle" font-size="11" fill="currentColor" opacity="0.65">financeiro · contrato · inativação</text><line x1="380" y1="582" x2="380" y2="604" stroke="currentColor" stroke-opacity="0.35" stroke-width="1.5" marker-end="url(#pta)"></line><rect x="280" y="600" width="200" height="34" rx="8" fill="color-mix(in srgb, #0891b2 9%, transparent)" stroke="#0891b2" stroke-width="1.5"></rect><text x="380.0" y="627" text-anchor="middle" font-size="13" font-weight="600" fill="#0891b2">Cliente inativado</text></svg></div><p class="text-foreground/70 text-xs">Nenhuma dessas caixas está no código — todas são configuração, em Serviços e Obrigações. Acrescentar uma etapa de retenção antes da pergunta, ou fazer o Lucro Real seguir por um ramo próprio, é mexer no editor, sem publicação nova.</p></div></div></div><div class="relative flex flex-col min-w-0 break-words bg-card text-card-foreground bg-clip-border border-0 rounded-[.25rem] shadow-[0_1px_2px_rgba(56,65,74,0.15)]"><div class="flex-1 p-5 space-y-3"><div class="flex items-center gap-2 pb-2 border-b"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="h-4 w-4" style="color: #10b981;"><rect x="5" y="2" width="14" height="20" rx="7"></rect><path d="M12 6v4"></path></svg><h3 class="text-sm font-bold" id="passo-a-passo" style="color: #10b981;">Passo a passo — o comercial recebe o pedido</h3></div><div class="space-y-2 text-sm"><div class="flex gap-3"><span class="shrink-0 flex items-center justify-center w-6 h-6 rounded-full bg-primary/10 text-primary text-xs font-bold">1</span><div><span class="font-semibold text-foreground block">Abra a ficha do cliente</span><span class="text-foreground/70">Em <strong>Cadastros → Clientes</strong>, clique na razão social. Você também chega pelo menu de três pontos da linha.</span></div></div><div class="flex gap-3"><span class="shrink-0 flex items-center justify-center w-6 h-6 rounded-full bg-primary/10 text-primary text-xs font-bold">2</span><div><span class="font-semibold text-foreground block">Registre o pedido de encerramento</span><span class="text-foreground/70">Informe <strong>por qual canal</strong> o cliente avisou (telefone, e-mail, WhatsApp, presencial), o <strong>motivo</strong> e a <strong>data pretendida</strong>, se ele tiver dado uma. Só o motivo é obrigatório — data você quase nunca tem no primeiro contato, e o campo não deve travar o registro.</span></div></div><div class="flex gap-3"><span class="shrink-0 flex items-center justify-center w-6 h-6 rounded-full bg-primary/10 text-primary text-xs font-bold">3</span><div><span class="font-semibold text-foreground block">Confira que o cliente continua ativo</span><span class="text-foreground/70">Ele ganha a marca de <strong>encerramento solicitado</strong>, mas segue na lista de ativos. As áreas continuam entregando o que é devido até a data ser definida.</span></div></div><div class="flex gap-3"><span class="shrink-0 flex items-center justify-center w-6 h-6 rounded-full bg-primary/10 text-primary text-xs font-bold">4</span><div><span class="font-semibold text-foreground block">A execução aparece parada, esperando</span><span class="text-foreground/70">Em <strong>Serviços e Obrigações</strong> surge o Offboarding daquele cliente, com status <strong>aguardando início</strong>. Ela não anda sozinha — é a trava contra o registro equivocado.</span></div></div><div class="rounded-md border-l-4 p-3 text-sm" style="border-color: #d97706; background: color-mix(in srgb, #d97706 8%, transparent);"><strong>Registrou por engano?</strong> Cancele a solicitação na própria ficha. O estado volta ao normal e fica o registro no histórico de que houve e foi desfeito. Se a execução já tiver sido confirmada, quem a cancela é o gestor do fluxo — assim o histórico do que já andou não se perde.</div></div></div></div><div class="relative flex flex-col min-w-0 break-words bg-card text-card-foreground bg-clip-border border-0 rounded-[.25rem] shadow-[0_1px_2px_rgba(56,65,74,0.15)]"><div class="flex-1 p-5 space-y-3"><div class="flex items-center gap-2 pb-2 border-b"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="h-4 w-4" style="color: #10b981;"><path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2"></path><circle cx="9" cy="7" r="4"></circle><path d="M22 21v-2a4 4 0 0 0-3-3.87"></path></svg><h3 class="text-sm font-bold" id="quem-faz" style="color: #10b981;">O que cada um faz depois</h3></div><div class="space-y-2 text-sm"><div class="flex flex-col sm:flex-row sm:items-baseline gap-1 sm:gap-3"><span class="font-semibold text-foreground sm:w-44 shrink-0">Comercial</span><span class="text-foreground/70">Confirma a execução, responde se a saída é imediata ou marcada, conduz o distrato e fala com o cliente até o fim.</span></div><div class="flex flex-col sm:flex-row sm:items-baseline gap-1 sm:gap-3"><span class="font-semibold text-foreground sm:w-44 shrink-0">Líder de cada área</span><span class="text-foreground/70">Registra a <strong>data de encerramento da sua área</strong>, conclui as entregas em aberto e devolve documentos e acessos. Enquanto a data não for registrada, a área continua aparecendo como contratada.</span></div><div class="flex flex-col sm:flex-row sm:items-baseline gap-1 sm:gap-3"><span class="font-semibold text-foreground sm:w-44 shrink-0">Financeiro</span><span class="text-foreground/70">Confere pendências antes do fechamento — é a última chance de cobrar o que ficou.</span></div><div class="flex flex-col sm:flex-row sm:items-baseline gap-1 sm:gap-3"><span class="font-semibold text-foreground sm:w-44 shrink-0">Quem inativa</span><span class="text-foreground/70">Só no fim. Inativar antes de as áreas encerrarem é justamente o que produz cliente inativo com serviço em aberto.</span></div></div></div></div><div class="relative flex flex-col min-w-0 break-words bg-card text-card-foreground bg-clip-border border-0 rounded-[.25rem] shadow-[0_1px_2px_rgba(56,65,74,0.15)]"><div class="flex-1 p-5 space-y-3"><div class="flex items-center gap-2 pb-2 border-b"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="h-4 w-4" style="color: #d97706;"><path d="m21.73 18-8-14a2 2 0 0 0-3.48 0l-8 14A2 2 0 0 0 4 21h16a2 2 0 0 0 1.73-3"></path><path d="M12 9v4"></path><path d="M12 17h.01"></path></svg><h3 class="text-sm font-bold" id="cuidados" style="color: #d97706;">Cuidados que evitam retrabalho</h3></div><div class="space-y-2 text-sm"><ul class="list-disc pl-5 space-y-1 text-foreground/70"><li><strong>Não inative direto pela listagem</strong> quando houver pedido formal de encerramento. A inativação em lote é para limpeza de cadastro; para saída de cliente, o caminho é o pedido, que aciona a cadeia.</li><li><strong>Registre a data de saída.</strong> Sem ela não há prazo a contar nem indicador que funcione — e não dá para saber há quanto tempo o cliente saiu.</li><li><strong>Encerre a área, não só o cliente.</strong> A área contratada sem data de encerramento é o que faz alguém continuar trabalhando meses depois.</li><li><strong>Cliente com filiais:</strong> ao inativar, o sistema pergunta se o encerramento alcança os CNPJs vinculados. Leia a lista antes de escolher "o grupo inteiro".</li></ul></div></div></div><div class="relative flex flex-col min-w-0 break-words bg-card text-card-foreground bg-clip-border border-0 rounded-[.25rem] shadow-[0_1px_2px_rgba(56,65,74,0.15)]"><div class="flex-1 p-5 space-y-3"><div class="flex items-center gap-2 pb-2 border-b"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="h-4 w-4" style="color: #0891b2;"><circle cx="12" cy="12" r="10"></circle><path d="M9.09 9a3 3 0 0 1 5.83 1c0 2-3 3-3 3"></path><path d="M12 17h.01"></path></svg><h3 class="text-sm font-bold" id="faq" style="color: #0891b2;">Perguntas frequentes</h3></div><div class="space-y-2 text-sm"><div class="space-y-3"><div><span class="font-semibold text-foreground block">O cliente para de ser atendido quando eu registro o pedido?</span><span class="text-foreground/70">Não. Ele continua ATIVO e as áreas seguem entregando. O pedido só inicia a conversa interna sobre a saída.</span></div><div><span class="font-semibold text-foreground block">O fluxo não abriu. E agora?</span><span class="text-foreground/70">O histórico do cliente registra o que o gatilho fez e o que deixou de fazer, com o motivo — serviço inativo, condição não atendida ou execução já em aberto para aquele cliente. Não fica no escuro.</span></div><div><span class="font-semibold text-foreground block">O cliente desistiu de sair.</span><span class="text-foreground/70">Cancele a solicitação na ficha. Se a execução já tinha sido confirmada e andado, cancele-a também em Serviços e Obrigações.</span></div><div><span class="font-semibold text-foreground block">Dá para ter um fluxo diferente por tipo de cliente?</span><span class="text-foreground/70">Sim. O gatilho aceita condição — por exemplo, Lucro Real seguir por um fluxo com transição fiscal mais longa. É configuração, não desenvolvimento.</span></div><div><span class="font-semibold text-foreground block">Por que a confirmação, se dá trabalho?</span><span class="text-foreground/70">Porque o custo do erro é assimétrico. Confirmar leva um clique; um distrato aberto por engano chega ao cliente.</span></div></div></div></div></div></div>',
  true,
  0,
  true,
  NULL,
  now(),
  now()
WHERE NOT EXISTS (SELECT 1 FROM faq_artigos WHERE slug = 'encerramento-cliente');
